1	use super::constants::*;
2	use super::handshake;
3	use super::peer::PeerInner;
4	use super::router;
5	use super::timers::Timers;
6	
7	use super::queue::ParallelQueue;
8	use super::workers::HandshakeJob;
9	
10	use super::tun::Tun;
11	use super::udp::UDP;
12	
13	use super::workers::{handshake_worker, tun_worker, udp_worker};
14	
15	use std::fmt;
16	use std::thread;
17	
18	use std::ops::Deref;
19	use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
20	use std::sync::Arc;
21	use std::sync::Condvar;
22	use std::sync::Mutex as StdMutex;
23	use std::time::Instant;
24	
25	use rand::rngs::OsRng;
26	use rand::Rng;
27	
28	use hjul::Runner;
29	use spin::{Mutex, RwLock};
30	use x25519_dalek::{PublicKey, StaticSecret};
31	
32	pub struct WireguardInner<T: Tun, B: UDP> {
33	    // identifier (for logging)
34	    pub id: u32,
35	
36	    // timer wheel
37	    pub runner: Mutex<Runner>,
38	
39	    // device enabled
40	    pub enabled: RwLock<bool>,
41	
42	    // number of tun readers
43	    pub tun_readers: WaitCounter,
44	
45	    // current MTU
46	    pub mtu: AtomicUsize,
47	
48	    // peer map
49	    #[allow(clippy::type_complexity)]
50	    pub peers: RwLock<
51	        handshake::Device<router::PeerHandle<B::Endpoint, PeerInner<T, B>, T::Writer, B::Writer>>,
52	    >,
53	
54	    // cryptokey router
55	    pub router: router::Device<B::Endpoint, PeerInner<T, B>, T::Writer, B::Writer>,
56	
57	    // handshake related state
58	    pub last_under_load: Mutex<Instant>,
59	    pub pending: AtomicUsize, // number of pending handshake packets in queue
60	    pub queue: ParallelQueue<HandshakeJob<B::Endpoint>>,
61	}
62	
63	pub struct WireGuard<T: Tun, B: UDP> {
64	    inner: Arc<WireguardInner<T, B>>,
65	}
66	
67	pub struct WaitCounter(StdMutex<usize>, Condvar);
68	
69	impl<T: Tun, B: UDP> fmt::Display for WireGuard<T, B> {
70	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
71	        write!(f, "wireguard({:x})", self.id)
72	    }
73	}
74	
75	impl<T: Tun, B: UDP> Deref for WireGuard<T, B> {
76	    type Target = WireguardInner<T, B>;
77	    fn deref(&self) -> &Self::Target {
78	        &self.inner
79	    }
80	}
81	
82	impl<T: Tun, B: UDP> Clone for WireGuard<T, B> {
83	    fn clone(&self) -> Self {
84	        WireGuard {
85	            inner: self.inner.clone(),
86	        }
87	    }
88	}
89	
90	#[allow(clippy::mutex_atomic)]
91	impl WaitCounter {
92	    pub fn wait(&self) {
93	        let mut nread = self.0.lock().unwrap();
94	        while *nread > 0 {
95	            nread = self.1.wait(nread).unwrap();
96	        }
97	    }
98	
99	    fn new() -> Self {
100	        Self(StdMutex::new(0), Condvar::new())
101	    }
102	
103	    fn decrease(&self) {
104	        let mut nread = self.0.lock().unwrap();
105	        assert!(*nread > 0);
106	        *nread -= 1;
107	        if *nread == 0 {
108	            self.1.notify_all();
109	        }
110	    }
111	
112	    fn increase(&self) {
113	        *self.0.lock().unwrap() += 1;
114	    }
115	}
116	
117	impl<T: Tun, B: UDP> WireGuard<T, B> {
118	    /// Brings the WireGuard device down.
119	    /// Usually called when the associated interface is brought down.
120	    ///
121	    /// This stops any further action/timer on any peer
122	    /// and prevents transmission of further messages,
123	    /// however the device retrains its state.
124	    ///
125	    /// The instance will continue to consume and discard messages
126	    /// on both ends of the device.
127	    pub fn down(&self) {
128	        // ensure exclusive access (to avoid race with "up" call)
129	        let mut enabled = self.enabled.write();
130	
131	        // check if already down
132	        if !(*enabled) {
133	            return;
134	        }
135	
136	        // set mtu
137	        self.mtu.store(0, Ordering::Relaxed);
138	
139	        // avoid transmission from router
140	        self.router.down();
141	
142	        // set all peers down (stops timers)
143	        for (_, peer) in self.peers.write().iter() {
144	            peer.stop_timers();
145	            peer.down();
146	        }
147	
148	        *enabled = false;
149	    }
150	
151	    /// Brings the WireGuard device up.
152	    /// Usually called when the associated interface is brought up.
153	    pub fn up(&self, mtu: usize) {
154	        // ensure exclusive access (to avoid race with "up" call)
155	        let mut enabled = self.enabled.write();
156	
157	        // set mtu
158	        self.mtu.store(mtu, Ordering::Relaxed);
159	
160	        // check if already up
161	        if *enabled {
162	            return;
163	        }
164	
165	        // enable transmission from router
166	        self.router.up();
167	
168	        // set all peers up (restarts timers)
169	        for (_, peer) in self.peers.write().iter() {
170	            peer.up();
171	            peer.start_timers();
172	        }
173	
174	        *enabled = true;
175	    }
176	
177	    pub fn clear_peers(&self) {
178	        self.peers.write().clear();
179	    }
180	
181	    pub fn remove_peer(&self, pk: &PublicKey) {
182	        let _ = self.peers.write().remove(pk);
183	    }
184	
185	    pub fn set_key(&self, sk: Option<StaticSecret>) {
186	        let mut peers = self.peers.write();
187	        peers.set_sk(sk);
188	        self.router.clear_sending_keys();
189	    }
190	
191	    pub fn get_sk(&self) -> Option<StaticSecret> {
192	        self.peers
193	            .read()
194	            .get_sk()
195	            .map(|sk| StaticSecret::from(sk.to_bytes()))
196	    }
197	
198	    pub fn set_psk(&self, pk: PublicKey, psk: [u8; 32]) -> bool {
199	        self.peers.write().set_psk(pk, psk).is_ok()
200	    }
201	    pub fn get_psk(&self, pk: &PublicKey) -> Option<[u8; 32]> {
202	        self.peers.read().get_psk(pk).ok()
203	    }
204	
205	    pub fn add_peer(&self, pk: PublicKey) -> bool {
206	        let mut peers = self.peers.write();
207	        if peers.contains_key(&pk) {
208	            return false;
209	        }
210	
211	        // prevent up/down while inserting
212	        let enabled = self.enabled.read();
213	
214	        // create timers (lookup by public key)
215	        let timers = Timers::new::<T, B>(self.clone(), pk, *enabled);
216	
217	        // create new router peer
218	        let peer: router::PeerHandle<B::Endpoint, PeerInner<T, B>, T::Writer, B::Writer> =
219	            self.router.new_peer(PeerInner {
220	                id: OsRng.gen(),
221	                pk,
222	                wg: self.clone(),
223	                walltime_last_handshake: Mutex::new(None),
224	                last_handshake_sent: Mutex::new(Instant::now() - TIME_HORIZON),
225	                handshake_queued: AtomicBool::new(false),
226	                rx_bytes: AtomicU64::new(0),
227	                tx_bytes: AtomicU64::new(0),
228	                timers: RwLock::new(timers),
229	            });
230	
231	        // finally, add the peer to the handshake device
232	        peers.add(pk, peer).is_ok()
233	    }
234	
235	    /// Begin consuming messages from the reader.
236	    /// Multiple readers can be added to support multi-queue and individual Ipv6/Ipv4 sockets interfaces
237	    ///
238	    /// Any previous reader thread is stopped by closing the previous reader,
239	    /// which unblocks the thread and causes an error on reader.read
240	    pub fn add_udp_reader(&self, reader: B::Reader) {
241	        let wg = self.clone();
242	        thread::spawn(move || {
243	            udp_worker(&wg, reader);
244	        });
245	    }
246	
247	    pub fn set_writer(&self, writer: B::Writer) {
248	        self.router.set_outbound_writer(writer);
249	    }
250	
251	    pub fn add_tun_reader(&self, reader: T::Reader) {
252	        let wg = self.clone();
253	
254	        // increment reader count
255	        wg.tun_readers.increase();
256	
257	        // start worker
258	        thread::spawn(move || {
259	            tun_worker(&wg, reader);
260	            wg.tun_readers.decrease();
261	        });
262	    }
263	
264	    pub fn wait(&self) {
265	        self.tun_readers.wait();
266	    }
267	
268	    pub fn new(writer: T::Writer) -> WireGuard<T, B> {
269	        // workers equal to number of physical cores
270	        let cpus = num_cpus::get();
271	
272	        // create handshake queue
273	        let (tx, mut rxs) = ParallelQueue::new(cpus, 128);
274	
275	        // create router
276	        let router: router::Device<B::Endpoint, PeerInner<T, B>, T::Writer, B::Writer> =
277	            router::Device::new(num_cpus::get(), writer);
278	
279	        // create arc to state
280	        let wg = WireGuard {
281	            inner: Arc::new(WireguardInner {
282	                enabled: RwLock::new(false),
283	                tun_readers: WaitCounter::new(),
284	                id: OsRng.gen(),
285	                mtu: AtomicUsize::new(0),
286	                last_under_load: Mutex::new(Instant::now() - TIME_HORIZON),
287	                router,
288	                pending: AtomicUsize::new(0),
289	                peers: RwLock::new(handshake::Device::new()),
290	                runner: Mutex::new(Runner::new(TIMERS_TICK, TIMERS_SLOTS, TIMERS_CAPACITY)),
291	                queue: tx,
292	            }),
293	        };
294	
295	        // start handshake workers
296	        while let Some(rx) = rxs.pop() {
297	            let wg = wg.clone();
298	            thread::spawn(move || handshake_worker(&wg, rx));
299	        }
300	
301	        wg
302	    }
303	}
304

