195	fn start_listener<T: tun::Tun, B: udp::PlatformUDP>(
196	    mut cfg: MutexGuard<Inner<T, B>>,
197	) -> Result<(), ConfigError> {
198	    cfg.bind = None;
199	
200	    // create new listener
201	    let (mut readers, writer, mut owner) = match B::bind(cfg.port) {
202	        Ok(r) => r,
203	        Err(_) => {
204	            return Err(ConfigError::FailedToBind);
205	        }
206	    };
207	
208	    // set fwmark
209	    let _ = owner.set_fwmark(cfg.fwmark); // TODO: handle
210	
211	    // set writer on WireGuard
212	    cfg.wireguard.set_writer(writer);
213	
214	    // add readers
215	    while let Some(reader) = readers.pop() {
216	        cfg.wireguard.add_udp_reader(reader);
217	    }
218	
219	    // create new UDP state
220	    cfg.bind = Some(owner);
221	    Ok(())
222	}
