47	// C := Hash(Construction)
48	const INITIAL_CK: [u8; SIZE_CK] = [
49	    0x60, 0xe2, 0x6d, 0xae, 0xf3, 0x27, 0xef, 0xc0, 0x2e, 0xc3, 0x35, 0xe2, 0xa0, 0x25, 0xd2, 0xd0,
50	    0x16, 0xeb, 0x42, 0x06, 0xf8, 0x72, 0x77, 0xf5, 0x2d, 0x38, 0xd1, 0x98, 0x8b, 0x78, 0xcd, 0x36,
51	];
52	
53	// H := Hash(C || Identifier)
54	const INITIAL_HS: [u8; SIZE_HS] = [
55	    0x22, 0x11, 0xb3, 0x61, 0x08, 0x1a, 0xc5, 0x66, 0x69, 0x12, 0x43, 0xdb, 0x45, 0x8a, 0xd5, 0x32,
56	    0x2d, 0x9c, 0x6c, 0x66, 0x22, 0x93, 0xe8, 0xb7, 0x0e, 0xe1, 0x9c, 0x65, 0xba, 0x07, 0x9e, 0xf3,
57	];
58	
59	const ZERO_NONCE: [u8; 12] = [0u8; 12];
60	
61	macro_rules! HASH {
62	    ( $($input:expr),* ) => {{
63	        use blake2::Digest;
64	        let mut hsh = Blake2s::new();
65	        $(
66	            hsh.update($input);
67	        )*
68	        hsh.finalize()
69	    }};
70	}
71	
72	macro_rules! HMAC {
73	    ($key:expr, $($input:expr),*) => {{
74	        use hmac::{Mac, NewMac};
75	        let mut mac = HMACBlake2s::new_varkey($key).unwrap();
76	        $(
77	            mac.update($input);
78	        )*
79	        mac.finalize().into_bytes()
80	    }};
81	}
82	
83	macro_rules! KDF1 {
84	    ($ck:expr, $input:expr) => {{
85	        let mut t0 = HMAC!($ck, $input);
86	        let t1 = HMAC!(&t0, &[0x1]);
87	        t0.clear();
88	        t1
89	    }};
90	}
91	
92	macro_rules! KDF2 {
93	    ($ck:expr, $input:expr) => {{
94	        let mut t0 = HMAC!($ck, $input);
95	        let t1 = HMAC!(&t0, &[0x1]);
96	        let t2 = HMAC!(&t0, &t1, &[0x2]);
97	        t0.clear();
98	        (t1, t2)
99	    }};
100	}
101	
102	macro_rules! KDF3 {
103	    ($ck:expr, $input:expr) => {{
104	        let mut t0 = HMAC!($ck, $input);
105	        let t1 = HMAC!(&t0, &[0x1]);
106	        let t2 = HMAC!(&t0, &t1, &[0x2]);
107	        let t3 = HMAC!(&t0, &t2, &[0x3]);
108	        t0.clear();
109	        (t1, t2, t3)
110	    }};
111	}
112	
113	macro_rules! SEAL {
114	    ($key:expr, $ad:expr, $pt:expr, $ct:expr) => {
115	        ChaCha20Poly1305::new(GenericArray::from_slice($key))
116	            .encrypt(&ZERO_NONCE.into(), Payload { msg: $pt, aad: $ad })
117	            .map(|ct| $ct.copy_from_slice(&ct))
118	            .unwrap()
119	    };
120	}
121	
122	macro_rules! OPEN {
123	    ($key:expr, $ad:expr, $pt:expr, $ct:expr) => {
124	        ChaCha20Poly1305::new(GenericArray::from_slice($key))
125	            .decrypt(&ZERO_NONCE.into(), Payload { msg: $ct, aad: $ad })
126	            .map_err(|_| HandshakeError::DecryptionFailure)
127	            .map(|pt| $pt.copy_from_slice(&pt))
128	    };
129	}
