215	// Computes an X25519 shared secret.
216	//
217	// This function wraps dalek to add a zero-check.
218	// This is not recommended by the Noise specification,
219	// but implemented in the kernel with which we strive for absolute equivalent behavior.
220	#[inline(always)]
221	fn shared_secret(sk: &StaticSecret, pk: &PublicKey) -> Result<SharedSecret, HandshakeError> {
222	    let ss = sk.diffie_hellman(pk);
223	    if ss.as_bytes().ct_eq(&[0u8; 32]).into() {
224	        Err(HandshakeError::InvalidSharedSecret)
225	    } else {
226	        Ok(ss)
227	    }
228	}
