230	pub(super) fn create_initiation<R: RngCore + CryptoRng, O>(
231	    rng: &mut R,
232	    keyst: &KeyState,
233	    peer: &Peer<O>,
234	    pk: &PublicKey,
235	    local: u32,
236	    msg: &mut NoiseInitiation,
237	) -> Result<(), HandshakeError> {
238	    log::debug!("create initiation");
239	
240	    // check for zero shared-secret (see "shared_secret" note).
241	    if peer.ss.ct_eq(&[0u8; 32]).into() {
242	        return Err(HandshakeError::InvalidSharedSecret);
243	    }
244	
245	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
246	        // initialize state
247	
248	        let ck = INITIAL_CK;
249	        let hs = INITIAL_HS;
250	        let hs = HASH!(&hs, pk.as_bytes());
251	
252	        msg.f_type.set(TYPE_INITIATION as u32);
253	        msg.f_sender.set(local); // from us
254	
255	        // (E_priv, E_pub) := DH-Generate()
256	
257	        let eph_sk = StaticSecret::new(rng);
258	        let eph_pk = PublicKey::from(&eph_sk);
259	
260	        // C := Kdf(C, E_pub)
261	
262	        let ck = KDF1!(&ck, eph_pk.as_bytes());
263	
264	        // msg.ephemeral := E_pub
265	
266	        msg.f_ephemeral = *eph_pk.as_bytes();
267	
268	        // H := HASH(H, msg.ephemeral)
269	
270	        let hs = HASH!(&hs, msg.f_ephemeral);
271	
272	        // (C, k) := Kdf2(C, DH(E_priv, S_pub))
273	
274	        let (ck, key) = KDF2!(&ck, shared_secret(&eph_sk, &pk)?.as_bytes());
275	
276	        // msg.static := Aead(k, 0, S_pub, H)
277	
278	        SEAL!(
279	            &key,
280	            &hs,                 // ad
281	            keyst.pk.as_bytes(), // pt
282	            &mut msg.f_static    // ct || tag
283	        );
284	
285	        // H := Hash(H || msg.static)
286	
287	        let hs = HASH!(&hs, &msg.f_static[..]);
288	
289	        // (C, k) := Kdf2(C, DH(S_priv, S_pub))
290	
291	        let (ck, key) = KDF2!(&ck, &peer.ss);
292	
293	        // msg.timestamp := Aead(k, 0, Timestamp(), H)
294	
295	        SEAL!(
296	            &key,
297	            &hs,                  // ad
298	            &timestamp::now(),    // pt
299	            &mut msg.f_timestamp  // ct || tag
300	        );
301	
302	        // H := Hash(H || msg.timestamp)
303	
304	        let hs = HASH!(&hs, &msg.f_timestamp);
305	
306	        // update state of peer
307	
308	        *peer.state.lock() = State::InitiationSent {
309	            hs,
310	            ck,
311	            eph_sk,
312	            local,
313	        };
314	
315	        Ok(())
316	    })
317	}
