319	pub(super) fn consume_initiation<'a, O>(
320	    device: &'a Device<O>,
321	    keyst: &KeyState,
322	    msg: &NoiseInitiation,
323	) -> Result<(&'a Peer<O>, PublicKey, TemporaryState), HandshakeError> {
324	    log::debug!("consume initiation");
325	
326	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
327	        // initialize new state
328	
329	        let ck = INITIAL_CK;
330	        let hs = INITIAL_HS;
331	        let hs = HASH!(&hs, keyst.pk.as_bytes());
332	
333	        // C := Kdf(C, E_pub)
334	
335	        let ck = KDF1!(&ck, &msg.f_ephemeral);
336	
337	        // H := HASH(H, msg.ephemeral)
338	
339	        let hs = HASH!(&hs, &msg.f_ephemeral);
340	
341	        // (C, k) := Kdf2(C, DH(E_priv, S_pub))
342	
343	        let eph_r_pk = PublicKey::from(msg.f_ephemeral);
344	        let (ck, key) = KDF2!(&ck, shared_secret(&keyst.sk, &eph_r_pk)?.as_bytes());
345	
346	        // msg.static := Aead(k, 0, S_pub, H)
347	
348	        let mut pk = [0u8; 32];
349	
350	        OPEN!(
351	            &key,
352	            &hs,           // ad
353	            &mut pk,       // pt
354	            &msg.f_static  // ct || tag
355	        )?;
356	
357	        let peer = device.lookup_pk(&PublicKey::from(pk))?;
358	
359	        // check for zero shared-secret (see "shared_secret" note).
360	
361	        if peer.ss.ct_eq(&[0u8; 32]).into() {
362	            return Err(HandshakeError::InvalidSharedSecret);
363	        }
364	
365	        // reset initiation state
366	
367	        *peer.state.lock() = State::Reset;
368	
369	        // H := Hash(H || msg.static)
370	
371	        let hs = HASH!(&hs, &msg.f_static[..]);
372	
373	        // (C, k) := Kdf2(C, DH(S_priv, S_pub))
374	
375	        let (ck, key) = KDF2!(&ck, &peer.ss);
376	
377	        // msg.timestamp := Aead(k, 0, Timestamp(), H)
378	
379	        let mut ts = timestamp::ZERO;
380	
381	        OPEN!(
382	            &key,
383	            &hs,              // ad
384	            &mut ts,          // pt
385	            &msg.f_timestamp  // ct || tag
386	        )?;
387	
388	        // check and update timestamp
389	
390	        peer.check_replay_flood(device, &ts)?;
391	
392	        // H := Hash(H || msg.timestamp)
393	
394	        let hs = HASH!(&hs, &msg.f_timestamp);
395	
396	        // return state (to create response)
397	
398	        Ok((
399	            peer,
400	            PublicKey::from(pk),
401	            (msg.f_sender.get(), eph_r_pk, hs, ck),
402	        ))
403	    })
404	}
