/* Equality (for testing purposes) */

#[cfg(test)]
macro_rules! eq_as_bytes {
    ($type:path) => {
        impl PartialEq for $type {
            fn eq(&self, other: &Self) -> bool {
                self.as_bytes() == other.as_bytes()
            }
        }
        impl Eq for $type {}
    };
}

#[cfg(test)]
eq_as_bytes!(Initiation);

#[cfg(test)]
eq_as_bytes!(Response);

