320	    fn write6(fd: RawFd, buf: &[u8], dst: &mut EndpointV6) -> Result<(), io::Error> {
321	        log::debug!("sending IPv6 packet ({} fd, {} bytes)", fd, buf.len());
322	
323	        let mut iovs: [libc::iovec; 1] = [libc::iovec {
324	            iov_base: buf.as_ptr() as *mut core::ffi::c_void,
325	            iov_len: buf.len(),
326	        }];
327	
328	        let mut control = ControlHeaderV6 {
329	            hdr: libc::cmsghdr {
330	                cmsg_len: CMSG_LEN(mem::size_of::<libc::in6_pktinfo>()),
331	                cmsg_level: libc::IPPROTO_IPV6,
332	                cmsg_type: libc::IPV6_PKTINFO,
333	            },
334	            info: dst.info,
335	        };
336	
337	        debug_assert_eq!(
338	            control.hdr.cmsg_len % mem::size_of::<u32>(),
339	            0,
340	            "cmsg_len must be aligned to a long"
341	        );
342	
343	        debug_assert_eq!(
344	            dst.dst.sin6_family,
345	            libc::AF_INET6 as libc::sa_family_t,
346	            "this method only handles IPv6 destinations"
347	        );
348	
349	        let mut hdr = libc::msghdr {
350	            msg_name: safe_cast(&mut dst.dst),
351	            msg_namelen: mem::size_of_val(&dst.dst) as u32,
352	            msg_iov: iovs.as_mut_ptr(),
353	            msg_iovlen: iovs.len(),
354	            msg_control: safe_cast(&mut control),
355	            msg_controllen: mem::size_of_val(&control),
356	            msg_flags: 0,
357	        };
358	
359	        let ret = unsafe { libc::sendmsg(fd, &hdr, 0) };
360	
361	        if ret < 0 {
362	            if errno() == libc::EINVAL {
363	                log::trace!("clear source and retry");
364	                hdr.msg_control = ptr::null_mut();
365	                hdr.msg_controllen = 0;
366	                dst.info = unsafe { mem::zeroed() };
367	                return if unsafe { libc::sendmsg(fd, &hdr, 0) } < 0 {
368	                    Err(io::Error::new(
369	                        io::ErrorKind::NotConnected,
370	                        "failed to send IPv6 packet",
371	                    ))
372	                } else {
373	                    Ok(())
374	                };
375	            }
376	            return Err(io::Error::new(
377	                io::ErrorKind::NotConnected,
378	                "failed to send IPv6 packet",
379	            ));
380	        }
381	
382	        Ok(())
383	    }
