508	impl LinuxUDP {
509	    /* Bind on all IPv6 interfaces
510	     *
511	     * Arguments:
512	     *
513	     * - 'port', port to bind to (0 = any)
514	     *
515	     * Returns:
516	     *
517	     * Returns a tuple of the resulting port and socket.
518	     */
519	    fn bind6(port: u16) -> Result<(u16, RawFd), io::Error> {
520	        log::trace!("attempting to bind on IPv6 (port {})", port);
521	
522	        // create socket fd
523	        let fd: RawFd = unsafe { libc::socket(libc::AF_INET6, libc::SOCK_DGRAM, 0) };
524	        if fd < 0 {
525	            log::debug!("failed to create IPv6 socket (errno = {})", errno());
526	            return Err(io::Error::new(
527	                io::ErrorKind::Other,
528	                "failed to create socket",
529	            ));
530	        }
531	
532	        setsockopt_int(fd, libc::SOL_SOCKET, libc::SO_REUSEADDR, 1)?;
533	        setsockopt_int(fd, libc::IPPROTO_IPV6, libc::IPV6_RECVPKTINFO, 1)?;
534	        setsockopt_int(fd, libc::IPPROTO_IPV6, libc::IPV6_V6ONLY, 1)?;
535	
536	        const INADDR_ANY: libc::in6_addr = libc::in6_addr { s6_addr: [0; 16] };
537	
538	        // bind
539	        let mut sockaddr = libc::sockaddr_in6 {
540	            sin6_addr: INADDR_ANY,
541	            sin6_family: libc::AF_INET6 as libc::sa_family_t,
542	            sin6_port: port.to_be(), // convert to network (big-endian) byte-order
543	            sin6_scope_id: 0,
544	            sin6_flowinfo: 0,
545	        };
546	
547	        let err = unsafe {
548	            libc::bind(
549	                fd,
550	                safe_cast(&mut sockaddr),
551	                mem::size_of_val(&sockaddr).try_into().unwrap(),
552	            )
553	        };
554	        if err != 0 {
555	            log::debug!("failed to bind IPv6 socket (errno = {})", errno());
556	            return Err(io::Error::new(
557	                io::ErrorKind::Other,
558	                "failed to create socket",
559	            ));
560	        }
561	
562	        // get the assigned port
563	        let mut socklen: libc::socklen_t = mem::size_of_val(&sockaddr).try_into().unwrap();
564	        let err = unsafe {
565	            libc::getsockname(
566	                fd,
567	                safe_cast(&mut sockaddr),
568	                &mut socklen as *mut libc::socklen_t,
569	            )
570	        };
571	        if err != 0 {
572	            log::debug!("failed to get port of IPv6 socket (errno  = {})", errno());
573	            return Err(io::Error::new(
574	                io::ErrorKind::Other,
575	                "failed to create socket",
576	            ));
577	        }
578	
579	        // basic sanity checks
580	        let new_port = u16::from_be(sockaddr.sin6_port);
581	        debug_assert_eq!(socklen, mem::size_of::<libc::sockaddr_in6>() as u32);
582	        debug_assert_eq!(sockaddr.sin6_family, libc::AF_INET6 as libc::sa_family_t);
583	        debug_assert_eq!(new_port, if port != 0 { port } else { new_port });
584	        log::trace!("bound IPv6 socket (port {}, fd {})", new_port, fd);
585	        Ok((new_port, fd))
586	    }
587	
588	    /* Bind on all IPv4 interfaces.
589	     *
590	     * Arguments:
591	     *
592	     * - 'port', port to bind to (0 = any)
593	     *
594	     * Returns:
595	     *
596	     * Returns a tuple of the resulting port and socket.
597	     */
598	    fn bind4(port: u16) -> Result<(u16, RawFd), io::Error> {
599	        log::trace!("attempting to bind on IPv4 (port {})", port);
600	
601	        // create socket fd
602	        let fd: RawFd = unsafe { libc::socket(libc::AF_INET, libc::SOCK_DGRAM, 0) };
603	        if fd < 0 {
604	            log::debug!("failed to create IPv4 socket (errno = {})", errno());
605	            return Err(io::Error::new(
606	                io::ErrorKind::Other,
607	                "failed to create socket",
608	            ));
609	        }
610	
611	        setsockopt_int(fd, libc::SOL_SOCKET, libc::SO_REUSEADDR, 1)?;
612	        setsockopt_int(fd, libc::IPPROTO_IP, libc::IP_PKTINFO, 1)?;
613	
614	        const INADDR_ANY: libc::in_addr = libc::in_addr { s_addr: 0 };
615	
616	        // bind
617	        let mut sockaddr = libc::sockaddr_in {
618	            sin_addr: INADDR_ANY,
619	            sin_family: libc::AF_INET as libc::sa_family_t,
620	            sin_port: port.to_be(),
621	            sin_zero: [0; 8],
622	        };
623	
624	        let err = unsafe {
625	            libc::bind(
626	                fd,
627	                safe_cast(&mut sockaddr),
628	                mem::size_of_val(&sockaddr).try_into().unwrap(),
629	            )
630	        };
631	        if err != 0 {
632	            log::debug!("failed to bind IPv4 socket (errno = {})", errno());
633	            return Err(io::Error::new(
634	                io::ErrorKind::Other,
635	                "failed to create socket",
636	            ));
637	        }
638	
639	        // get the assigned port
640	        let mut socklen: libc::socklen_t = mem::size_of_val(&sockaddr).try_into().unwrap();
641	        let err = unsafe {
642	            libc::getsockname(
643	                fd,
644	                safe_cast(&mut sockaddr),
645	                &mut socklen as *mut libc::socklen_t,
646	            )
647	        };
648	        if err != 0 {
649	            log::debug!("failed to get port of IPv4 socket (errno = {})", errno());
650	            return Err(io::Error::new(
651	                io::ErrorKind::Other,
652	                "failed to create socket",
653	            ));
654	        }
655	
656	        // basic sanity checks
657	        let new_port = u16::from_be(sockaddr.sin_port);
658	        debug_assert_eq!(socklen, mem::size_of::<libc::sockaddr_in>() as u32);
659	        debug_assert_eq!(sockaddr.sin_family, libc::AF_INET as libc::sa_family_t);
660	        debug_assert_eq!(new_port, if port != 0 { port } else { new_port });
661	        log::trace!("bound IPv4 socket (port {}, fd {})", new_port, fd);
662	        Ok((new_port, fd))
663	    }
664	}
