666	impl PlatformUDP for LinuxUDP {
667	    type Owner = LinuxOwner;
668	
669	    #[allow(clippy::type_complexity)]
670	    #[allow(clippy::unnecessary_unwrap)]
671	    fn bind(mut port: u16) -> Result<(Vec<Self::Reader>, Self::Writer, Self::Owner), Self::Error> {
672	        log::debug!("bind to port {}", port);
673	
674	        // attempt to bind on ipv6
675	        let bind6 = Self::bind6(port);
676	        if let Ok((new_port, _)) = bind6 {
677	            port = new_port;
678	        }
679	
680	        // attempt to bind on ipv4 on the same port
681	        let bind4 = Self::bind4(port);
682	        if let Ok((new_port, _)) = bind4 {
683	            port = new_port;
684	        }
685	
686	        // check if failed to bind on both
687	        if bind4.is_err() && bind6.is_err() {
688	            log::trace!("failed to bind for either IP version");
689	            return Err(bind6.unwrap_err());
690	        }
691	
692	        let sock6 = bind6.ok().map(|(_, fd)| Arc::new(FD(fd)));
693	        let sock4 = bind4.ok().map(|(_, fd)| Arc::new(FD(fd)));
694	
695	        // create owner
696	        let owner = LinuxOwner {
697	            port,
698	            sock6: sock6.clone(),
699	            sock4: sock4.clone(),
700	        };
701	
702	        // create readers
703	        let mut readers: Vec<Self::Reader> = Vec::with_capacity(2);
704	        if let Some(sock) = sock6.clone() {
705	            readers.push(LinuxUDPReader::V6(sock))
706	        }
707	        if let Some(sock) = sock4.clone() {
708	            readers.push(LinuxUDPReader::V4(sock))
709	        }
710	        debug_assert!(!readers.is_empty());
711	
712	        // create writer
713	        let writer = LinuxUDPWriter {
714	            sock4: sock4.unwrap_or_else(|| Arc::new(FD(-1))),
715	            sock6: sock6.unwrap_or_else(|| Arc::new(FD(-1))),
716	        };
717	
718	        Ok((readers, writer, owner))
719	    }
720	}
